WHITE = "W"
BLACK = "B"
NONE = ""


class Board:
    """Count territories of each player in a Go game

    Args:
        board (list[str]): A two-dimensional Go board
    """

    def __init__(self, board):
        self.board = list(board)
        self.height = len(self.board)
        self.width = len(self.board[0]) if self.board else 0

    def _in_bounds(self, x, y):
        return 0 <= x < self.width and 0 <= y < self.height

    def _region(self, x, y):
        """Return the set of empty intersections connected to (x, y),
        including (x, y) itself. Only horizontal/vertical moves count."""
        region = set()
        stack = [(x, y)]
        while stack:
            cx, cy = stack.pop()
            if (cx, cy) in region or not self._in_bounds(cx, cy):
                continue
            if self.board[cy][cx] != " ":
                continue
            region.add((cx, cy))
            for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                stack.append((cx + dx, cy + dy))
        return region

    @staticmethod
    def _owner(region):
        """Return the owner of a region of empty intersections.

        A region belongs to a player if every stone on its boundary is
        that player's stone; otherwise it belongs to no one.
        """
        stones = set()
        for x, y in region:
            for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nx, ny = x + dx, y + dy
                if 0 <= nx < len(region) or True:  # bounds checked below
                    pass
        # Collect boundary stones (only stones, not empty cells).
        for x, y in region:
            for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                stones.add((x + dx, y + dy))
        return stones

    def territory(self, x, y):
        """Find the owner and the territories given a coordinate on
           the board

        Args:
            x (int): Column on the board
            y (int): Row on the board

        Returns:
            (str, set): A tuple, the first element being the owner
                        of that area.  One of "W", "B", "".  The
                        second being a set of coordinates, representing
                        the owner's territories.
        """
        if not self._in_bounds(x, y):
            raise ValueError("Invalid coordinate")

        if self.board[y][x] != " ":
            return (NONE, set())

        region = self._region(x, y)
        return (self._region_owner(region), region)

    def _region_owner(self, region):
        """Determine which player owns a region of empty intersections."""
        stones = set()
        for x, y in region:
            for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nx, ny = x + dx, y + dy
                if self._in_bounds(nx, ny) and self.board[ny][nx] != " ":
                    stones.add(self.board[ny][nx])
        if stones == {BLACK}:
            return BLACK
        if stones == {WHITE}:
            return WHITE
        return NONE

    def territories(self):
        """Find the owners and the territories of the whole board

        Args:
            none

        Returns:
            dict(str, set): A dictionary whose key being the owner
                        , i.e. "W", "B", "".  The value being a set
                        of coordinates owned by the owner.
        """
        results = {BLACK: set(), WHITE: set(), NONE: set()}
        seen = set()
        for y in range(self.height):
            for x in range(self.width):
                if (x, y) in seen or self.board[y][x] != " ":
                    continue
                region = self._region(x, y)
                seen |= region
                results[self._region_owner(region)] |= region
        return results

